local a=np.flip(base,1)
local selector=np.array({true,false,false,true,false,false,true,false,false,true,false,false},"bool")
local values=np.flip(base,2)
local ok,result=pcall(function() return np.place(a,selector,values) end)
assert(ok==true,"noncontiguous-values/complex128/reverse_rows/True: acceptance")
if ok then assert(result==nil,"noncontiguous-values/complex128/reverse_rows/True: return") end
eq(base:tolist(),{{np.complex(0.0,0.0),np.complex(0.0,0.0),np.complex(2.0,0.0),np.complex(3.0,0.0)},{np.complex(4.0,0.0),np.complex(5.0,0.0),np.complex(1.0,0.0),np.complex(7.0,0.0)},{np.complex(3.0,0.0),np.complex(9.0,0.0),np.complex(10.0,0.0),np.complex(2.0,0.0)}},"noncontiguous-values/complex128/reverse_rows/True")
eq(a.shape,{3,4},"noncontiguous-values/complex128/reverse_rows/True: shape")
eq(a.strides,{-64,16},"noncontiguous-values/complex128/reverse_rows/True: strides")
cases=cases+1
end
